class Solution { public TreeNode addOneRow(TreeNode root,int val,int depth){if(depth==1){TreeNode added=new TreeNode(val);added.left=root;return added;}insert(root,val,1,depth);return root;}private void insert(TreeNode node,int val,int current,int depth){if(node==null)return;if(current==depth-1){TreeNode oldLeft=node.left,oldRight=node.right;node.left=new TreeNode(val);node.right=new TreeNode(val);node.left.left=oldLeft;node.right.right=oldRight;return;}insert(node.left,val,current+1,depth);insert(node.right,val,current+1,depth);} }
